#!/usr/bin/env node
// Embeds the two Claude prompts as strings so the deployed shop (a single esbuild bundle) needs no
// files beside it. The .md files stay the source of truth; a launcher test fails if this output is stale.
import { readFileSync, writeFileSync } from "node:fs";

const dir = new URL("../apps/launcher/src/prompts/", import.meta.url);
const read = (name) => readFileSync(new URL(name, dir), "utf8");
const out = [
  "// Generated by scripts/gen-prompt-texts.mjs from compile.md and scenarios.md. Do not edit.",
  `export const COMPILE_PROMPT_TEMPLATE = ${JSON.stringify(read("compile.md"))};`,
  `export const SCENARIOS_PROMPT = ${JSON.stringify(read("scenarios.md"))};`,
  "",
].join("\n");
writeFileSync(new URL("texts.ts", dir), out);
